{
  "path": {
    "type": "TEXT",
    "hint": "Full path of the file or link: index name first, then the path inside the index (e.g. myindex/dir/file.txt). Ordinary TEXT: filter with path LIKE 'myindex/dir/%', GROUP BY, etc. In aggregate_sql_query, to use path in partial_sql or final_sql, carry it through per_directory_shape and partial_shape. Functions: ext(path) -> extension after the last dot, NULL if none; basename(path) -> last path component."
  },
  "dirpath": {
    "type": "TEXT",
    "hint": "Full path of the directory containing the file or link (e.g. myindex/dir). Filter with dirpath LIKE 'myindex/dir/%'. Functions: basename(dirpath) -> last path component."
  },
  "dname": {
    "type": "TEXT",
    "hint": "Base name of the containing directory only, not a path."
  },
  "dmode": {
    "type": "INT64",
    "hint": "Directory's st_mode as INT64 (decimal). Same bitmask rules as mode on file rows. Functions: modetotxt(dmode) -> 'drwxr-xr-x'."
  },
  "dnlink": {
    "type": "INT64",
    "hint": "directory unix number of links"
  },
  "duid": {
    "type": "INT64",
    "hint": "directory unix uid. Functions: uidtouser(duid) -> user name."
  },
  "dgid": {
    "type": "INT64",
    "hint": "directory unix gid. Functions: gidtogroup(dgid) -> group name."
  },
  "dsize": {
    "type": "INT64",
    "hint": "Directory row metadata size in bytes (the directory inode), not subtree total (see dtotsize/totsize). Functions: bytecat(dsize) -> size band (Zero, B, K, M, G, ...); human_readable_size(dsize) -> '1.5M'."
  },
  "dblksize": {
    "type": "INT64",
    "hint": "directory unix blksize for file"
  },
  "dblocks": {
    "type": "INT64",
    "hint": "directory unix number of blocks"
  },
  "datime": {
    "type": "INT64",
    "hint": "Directory unix access time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given, e.g. atime < <now_epoch> - 30 * 86400; do not hand-compute epochs. Functions: agecat(datime) -> age band (Secs, Mins, Hrs, Days, Wks, Mos, Yrs, Decs); epochtoage(datime, 'd') -> whole days old; strftime('%Y-%m', datime) -> date text."
  },
  "dmtime": {
    "type": "INT64",
    "hint": "Directory unix modification time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given, e.g. mtime < <now_epoch> - 30 * 86400; do not hand-compute epochs. Functions: agecat(dmtime) -> age band (Secs, Mins, Hrs, Days, Wks, Mos, Yrs, Decs); epochtoage(dmtime, 'd') -> whole days old; strftime('%Y-%m', dmtime) -> date text."
  },
  "dctime": {
    "type": "INT64",
    "hint": "Directory unix status-change time: seconds since epoch (INT64). For relative windows, compute cutoffs in SQL from the current time you were given; do not hand-compute epochs. Functions: agecat(dctime) -> age band (Secs, Mins, Hrs, Days, Wks, Mos, Yrs, Decs); epochtoage(dctime, 'd') -> whole days old; strftime('%Y-%m', dctime) -> date text."
  },
  "dlinkname": {
    "type": "TEXT",
    "hint": "directory unix string for link name"
  },
  "dtotfiles": {
    "type": "INT64",
    "hint": "directory number files. Functions: intcat(dtotfiles) -> count band (Zero, O, K, M, B, ...)."
  },
  "dtotlinks": {
    "type": "INT64",
    "hint": "directory summed links. Functions: intcat(dtotlinks) -> count band (Zero, O, K, M, B, ...)."
  },
  "dminuid": {
    "type": "INT64",
    "hint": "directory min uid. Functions: uidtouser(dminuid) -> user name."
  },
  "dmaxuid": {
    "type": "INT64",
    "hint": "directory max uid. Functions: uidtouser(dmaxuid) -> user name."
  },
  "dmingid": {
    "type": "INT64",
    "hint": "directory min gid. Functions: gidtogroup(dmingid) -> group name."
  },
  "dmaxgid": {
    "type": "INT64",
    "hint": "directory max gid. Functions: gidtogroup(dmaxgid) -> group name."
  },
  "dminsize": {
    "type": "INT64",
    "hint": "directory min size. Functions: bytecat(dminsize) -> size band (Zero, B, K, M, G, ...); human_readable_size(dminsize) -> '1.5M'."
  },
  "dmaxsize": {
    "type": "INT64",
    "hint": "directory max size. Functions: bytecat(dmaxsize) -> size band (Zero, B, K, M, G, ...); human_readable_size(dmaxsize) -> '1.5M'."
  },
  "dtotzero": {
    "type": "INT64",
    "hint": "directory number of zero-size files"
  },
  "dtotltk": {
    "type": "INT64",
    "hint": "directory number <= 1024"
  },
  "dtotmtk": {
    "type": "INT64",
    "hint": "directory number > 1024"
  },
  "totltm": {
    "type": "INT64",
    "hint": "number <= 1048576"
  },
  "dtotmtm": {
    "type": "INT64",
    "hint": "directory number > 1048576"
  },
  "dtotmtg": {
    "type": "INT64",
    "hint": "directory number <= 1073741824"
  },
  "dtotmtt": {
    "type": "INT64",
    "hint": "directory number > 1073741824"
