  },
  "linkname": {
    "type": "TEXT",
    "hint": "unix string for link name. Functions: basename(linkname) -> last path component."
  },
  "xattr_names": {
    "type": "BLOB",
    "hint": "concatenation of all extended attributes"
  },
  "crtime": {
    "type": "INT64",
    "hint": "create time epoch (some file systems provide). Functions: agecat(crtime) -> age band (Secs, Mins, Hrs, Days, Wks, Mos, Yrs, Decs); epochtoage(crtime, 'd') -> whole days old; strftime('%Y-%m', crtime) -> date text."
  },
  "ossint1": {
    "type": "INT64",
    "hint": "storage system specific integer"
  },
  "ossint2": {
    "type": "INT64",
    "hint": "storage system specific integer"
  },
  "ossint3": {
    "type": "INT64",
